-- Node: afe-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Suspected Amniotic Fluid Embolism","body":"[AFE Steps Summary](#/info/afe-steps-summary) — first-2-minutes checklist.\n\n**Amniotic Fluid Embolism is a clinical diagnosis of exclusion.** Classic triad: **hypoxia + hypotension + coagulopathy** in labor or within 30 min postpartum. Mortality 20–60%; neurologically intact survival depends on minutes, not hours. [1][2][3]\n\n**Prodrome in ~30%:** agitation, \"sense of doom,\" restlessness, shivering, paresthesias, metallic taste — **precedes collapse by seconds to minutes.** [5]\n\nIs the patient in labor, C-section, D&E, or within 30 min postpartum AND experiencing sudden cardiopulmonary collapse (SBP <90, SpO₂ <90, dyspnea, cyanosis, or arrest)?","citation":[1,2,3,5],"options":[{"label":"Yes — peripartum + sudden collapse","next":"afe-call","urgency":"critical"},{"label":"No — consider other diagnoses","description":"PE, anaphylaxis, sepsis, MI, eclampsia, hemorrhagic shock","next":"afe-ddx"}],"summary":"Peripartum sudden collapse + hypoxia + DIC — clinical dx of exclusion, ~30% have prodrome","safetyLevel":"critical"}'::jsonb
WHERE id = 'afe-start' AND tree_id = 'afe';

-- Node: afe-ddx (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Differential Diagnosis","body":"**Before committing to Amniotic Fluid Embolism, rule out treatable mimics:** [1][6]\n\n• **Pulmonary embolism** — bedside echo: RV strain without the fibrinolytic DIC pattern\n• **Anaphylaxis** — urticaria, bronchospasm, clear trigger; responds to epinephrine alone\n• **Septic shock** — fever, leukocytosis, source; slower onset\n• **Myocardial infarction** — ECG changes, troponin; rare peripartum but possible\n• **Eclampsia** — seizure, proteinuria, HTN (Amniotic Fluid Embolism typically hypotensive)\n• **Hemorrhagic shock** — identifiable bleeding source + responsive to volume; DIC is late\n• **Peripartum cardiomyopathy** — subacute onset, LV dysfunction, no DIC\n• **Air embolism / Local anesthetic toxicity** — context-specific (C-section, epidural placement)\n\n**[SMFM / Clark Diagnostic Criteria](#/info/afe-criteria)** — research-standard definition; do not wait for confirmation to treat empirically.","citation":[1,6],"next":"afe-call","summary":"Rule out PE, anaphylaxis, sepsis, MI, eclampsia, hemorrhage, PPCM, air/LAST — treat empirically"}'::jsonb
WHERE id = 'afe-ddx' AND tree_id = 'afe';

-- Node: afe-airway (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Airway & Oxygenation","body":"**Immediate intubation** — all Amniotic Fluid Embolism patients need a definitive airway. [1][2]\n\n• **100% FiO₂** — maximize oxygenation\n• **Smaller ETT (6.0–7.0)** — airway mucosal edema in pregnancy\n• **Rapid sequence** — etomidate 0.3 mg/kg or ketamine 1–2 mg/kg; avoid propofol (hypotension)\n• **PEEP 5–10 cm H₂O** initially, titrate up for hypoxemia\n• **Waveform capnography** immediately after intubation — ETCO₂ >20 mmHg = adequate CPR\n• **Aspiration risk is high** — apply cricoid pressure during bagging if not yet intubated\n\n**Difficult airway expected** — full-term pregnancy, airway edema, breast tissue, laryngeal edema from resuscitation.","citation":[1,2],"next":"afe-access","summary":"Intubate immediately, 100% FiO2, ETT 6.0-7.0, ETCO2 >20 = good CPR — expect difficult airway"}'::jsonb
WHERE id = 'afe-airway' AND tree_id = 'afe';

-- Node: afe-hemo (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Hemodynamic Support — RV-First Strategy","body":"**Amniotic Fluid Embolism shock = acute RV failure from pulmonary HTN.** Fluid overload worsens RV distension and septal shift. [1][3]\n\n**Vasopressors (first-line — start early, titrate aggressively):**\n• **[Norepinephrine](#/drug/norepinephrine/amniotic fluid embolism)** 0.05–0.5 mcg/kg/min — first choice (α > β)\n• **[Vasopressin](#/drug/vasopressin/amniotic fluid embolism)** 0.04 U/min — spares pulmonary vasculature, synergistic with norepi\n• **[Epinephrine](#/drug/epinephrine/amniotic fluid embolism)** 0.05–0.5 mcg/kg/min — if arrest or mixed shock\n\n**Inotropes (for RV failure with preserved SBP):**\n• **[Milrinone](#/drug/milrinone/amniotic fluid embolism)** 0.25–0.75 mcg/kg/min (NO bolus — drops SBP)\n• **[Dobutamine](#/drug/dobutamine/amniotic fluid embolism)** 2.5–10 mcg/kg/min\n\n**Pulmonary vasodilators (selective — will not drop SBP):**\n• **Inhaled nitric oxide** 20–40 ppm (max 80)\n• **Inhaled epoprostenol (Flolan)** 50 ng/kg/min nebulized\n• **Inhaled milrinone** 5 mg nebulized\n\n**Fluids:** crystalloid 500 mL bolus MAX during initial resuscitation; after that, blood products preferred. CVP >12 or RV dilation on bedside echo = STOP fluids.","citation":[1,3],"next":"afe-mtp","summary":"RV failure physiology — pressors first (norepi + vaso), inotropes (milrinone no bolus), iNO — limit crystalloid"}'::jsonb
WHERE id = 'afe-hemo' AND tree_id = 'afe';

-- Node: afe-mtp (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":5,"title":"DIC / Massive Transfusion","body":"**Activate MTP at diagnosis — do not wait for labs.** Amniotic Fluid Embolism coagulopathy is often fibrinolytic PLUS consumptive. [10][12]\n\n**[MTP + DIC Targets](#/info/afe-mtp)** — full transfusion table.\n\n**Initial orders:**\n• **PRBC : FFP : Platelets = 1:1:1** (standard MTP pack)\n• **Fibrinogen target ≥150–200 mg/dL** (obstetric threshold higher than trauma)\n• **[Cryoprecipitate](#/drug/cryoprecipitate/amniotic fluid embolism)** 10 units (or 2 pooled bags) — raises fibrinogen ~70–100 mg/dL\n• **Fibrinogen concentrate** 2–4 g IV (if available — faster than cryo, volume-sparing)\n• [Platelets](#/drug/platelets/massive transfusion) — keep >50 ×10⁹/L (>75 if ongoing bleeding)\n\n**TEG/ROTEM-guided resuscitation:**\n• FIBTEM A5 <12 mm → fibrinogen\n• EXTEM CT prolonged → FFP or PCC\n• LY30 >3% → TXA\n\nIs there active hemorrhage (vaginal bleeding, oozing from IV sites, surgical field bleeding)?","citation":[10,12],"options":[{"label":"Yes — active bleeding + coagulopathy","next":"afe-txa","urgency":"critical"},{"label":"No bleeding yet — trend labs","description":"Monitor fibrinogen, platelets, PT/PTT q30-60 min","next":"afe-ecmo"}],"summary":"MTP 1:1:1 + fibrinogen >150-200 — activate at dx, do not wait for labs","safetyLevel":"critical"}'::jsonb
WHERE id = 'afe-mtp' AND tree_id = 'afe';

-- Node: afe-txa (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"TXA + Antifibrinolytics","body":"**[Tranexamic Acid (TXA)](#/drug/tranexamic-acid/amniotic fluid embolism) 1 g IV over 10 min → repeat 1 g IV over 10 min at 30 min if bleeding continues.** [10]\n\n**WOMAN trial (Lancet 2017):** TXA within 3 h of postpartum hemorrhage onset reduces death from bleeding. NNT 267. No increase in thromboembolic events. Give early — effect diminishes after 3 h.\n\n**Avoid rFVIIa** — Leighton 2011 systematic review showed increased thrombotic death in Amniotic Fluid Embolism patients who received rFVIIa. Reserve only for refractory bleeding AFTER maximal standard MTP has failed and surgical bleeding is controlled. [11]\n\n**Surgical/procedural hemostasis:**\n• Bakri balloon or uterine packing for uterine atony\n• [Oxytocin](#/drug/oxytocin/amniotic fluid embolism) 20 units in 1 L NS at 250 mL/hr + methylergonovine + carboprost if not contraindicated\n• Consider hysterectomy if refractory — do not delay for dying patient\n\n**Trend labs q30–60 min:** fibrinogen, platelets, PT/PTT, TEG.","citation":[10,11],"next":"afe-ecmo","summary":"TXA 1g IV over 10 min x 2 doses <3h — avoid rFVIIa (thrombotic death in Amniotic Fluid Embolism)"}'::jsonb
WHERE id = 'afe-txa' AND tree_id = 'afe';

-- Node: afe-ecmo (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":5,"title":"ECMO / Mechanical Circulatory Support","body":"**Consider VA-ECMO early — case series show survival 60–80% with ECMO vs ~30% without.** [1][12]\n\n**Indications — call ECMO team DURING the resuscitation, not after:**\n• Prolonged CPR (>10 min) without ROSC\n• Refractory RV failure despite pressors + inotropes + pulmonary vasodilators\n• Refractory hypoxemia (PaO₂/FiO₂ <100) despite optimal ventilation\n• Patient is a reasonable candidate (not pre-existing irreversible multi-organ failure)\n\n**Alternatives if ECMO unavailable or delayed:**\n• **Impella RP** — percutaneous RV assist\n• **RVAD** — surgical RV assist\n• **Intra-aortic balloon pump (IABP)** — limited utility in RV-predominant Amniotic Fluid Embolism shock\n\n**Logistics:**\n• Peripheral VA-ECMO (femoral artery + vein) is fastest\n• If post-hysterotomy, central cannulation may be feasible during surgical exposure\n• Transfer to ECMO-capable center if not on site — do not delay\n\nHas the patient achieved ROSC AND stabilized hemodynamically?","citation":[1,12],"options":[{"label":"Yes — ROSC + stabilizing","next":"afe-postrosc","urgency":"critical"},{"label":"No — refractory arrest or shock","description":"Continue ACLS + ECMO cannulation","next":"afe-refractory"}],"summary":"ECMO survival 60-80% vs 30% — call team during resus, not after; Impella RP / RVAD alternatives","safetyLevel":"critical"}'::jsonb
WHERE id = 'afe-ecmo' AND tree_id = 'afe';

-- Node: afe-refractory (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Refractory Arrest — Extended Resuscitation","body":"**Amniotic Fluid Embolism is one of the few arrest scenarios where extended CPR and \"futile-appearing\" resuscitation can still produce neurologically intact survivors.** Do not terminate early without team consensus. [7][8][12]\n\n**Optimize every domain:**\n• **CPR quality** — rotate compressors q2 min, ETCO₂ >20 mmHg target, mechanical CPR device if available\n• **LUD** — confirm ongoing, two-handed push-to-left\n• **Hysterotomy** — if not yet performed and ≥20 wk, do it NOW (relieves aortocaval compression)\n• **ECMO cannulation** — continue CPR during cannulation; ROSC after ECMO start is acceptable\n• **Product replacement** — continue MTP 1:1:1 + cryo + TXA\n• **Pressors/inotropes** — push-dose epi/phenylephrine between ACLS rounds if IV infusions not tolerated\n\n**Reversible causes checklist (Hs and Ts, pregnancy-modified):**\n• Hypoxia — airway, FiO₂ 100%, PEEP\n• Hypovolemia — blood products, not crystalloid\n• Hyper/hypo-K — especially if extensive product replacement\n• H+ (acidosis) — bicarb for pH <7.1 with hemodynamic instability\n• Tension PTX — POCUS, needle decompress if suspected\n• Tamponade — bedside echo\n• Thrombosis — Amniotic Fluid Embolism itself; also true PE in this population\n• Toxins — magnesium in eclampsia (calcium gluconate 1 g IV reverses)\n\n**Termination criteria:** senior OB + EM + CCM consensus; ETCO₂ <10 mmHg after 30+ min of optimized CPR; no reversible cause remaining. Document thoroughly.","citation":[7,8,12],"next":"afe-postrosc","summary":"Extended CPR warranted in Amniotic Fluid Embolism — optimize every domain, consider ECMO, do not terminate early","safetyLevel":"critical"}'::jsonb
WHERE id = 'afe-refractory' AND tree_id = 'afe';

-- Node: afe-complete (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":6,"title":"Amniotic Fluid Embolism Resuscitation Complete","body":"**Resuscitation goals achieved. Transition to ICU care.** [1][2]\n\n**Before handoff, confirm:**\n✓ Definitive airway secured, appropriate ventilator settings\n✓ Hemodynamics stable on documented pressor regimen\n✓ MTP products given — documented ratios, fibrinogen >150, platelets >50\n✓ TXA dosed ×1 (±repeat), hemostasis achieved\n✓ Uterus firm or packed; Foley in place; bladder not distended\n✓ Neonatal team has infant — APGAR documented, disposition clear\n✓ Imaging post-stabilization: CXR (ETT position, ARDS), bedside echo (RV/LV function)\n✓ ICU bed, ECMO status if on support, continuous EEG if comatose\n✓ **Code team debrief scheduled**\n✓ **Family updated — both mother and infant status**\n\n**Document clearly:**\n• Time of symptom onset, arrest, ROSC, hysterotomy\n• All drugs, doses, times\n• All blood products (PRBC, FFP, platelets, cryo, fibrinogen)\n• Decision points and team consensus moments\n• **Report case to AFE Foundation registry** — improves epidemiology and future care","citation":[1,2,3,12],"recommendation":"Transfer to ICU. TTM 32–36 °C × 24 h if comatose. Trend labs q1–2 h. Watch AKI/ARDS/Sheehan/delayed DIC. Maternal psychiatry consult before discharge. Report to AFE Registry.","confidence":"definitive","summary":"ICU transition with complete handoff, registry report, family/team debrief"}'::jsonb
WHERE id = 'afe-complete' AND tree_id = 'afe';

-- Node: dic-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"DIC — Recognition","body":"[DIC Steps Summary](#/info/dic-steps)\n\n**Disseminated Intravascular Coagulation (DIC)** is an acquired syndrome of systemic intravascular coagulation activation that consumes platelets and clotting factors, simultaneously causing microvascular thrombosis and bleeding. [1][2]\n\n**Always secondary** — DIC is never a primary diagnosis. Find and treat the underlying trigger. [1][3]\n\n**Mortality:** 31-86% depending on etiology and severity. The single most important determinant of survival is **prompt control of the underlying cause.** [2][3]\n\n**Most common triggers (overlapping in critically ill):** [1][2][3]\n• **Sepsis** (most common — gram-negative > gram-positive)\n• **Malignancy** (solid tumors and hematologic, especially APL)\n• **Trauma** (TBI, crush, burns)\n• **Obstetric emergencies** (placental abruption, Amniotic Fluid Embolism, retained products, severe preeclampsia/HELLP)\n• **Severe organ injury** (acute pancreatitis, fulminant hepatic failure)\n• **Vascular abnormalities** (giant hemangiomas, large aortic aneurysms — Kasabach-Merritt)\n\n**Two clinical phenotypes:** [2][4]\n• **Bleeding-dominant** — obstetric, trauma, APL\n• **Thrombotic-dominant** — sepsis, malignancy (Trousseau)","citation":[1,2,3,4],"next":"dic-suspect","calculatorLinks":[{"id":"dic-isth-score","label":"ISTH DIC Score"},{"id":"dic-jaam-score","label":"JAAM DIC Score"},{"id":"dic-sic-score","label":"SIC Score"}],"summary":"DIC is always secondary — find and treat the trigger; bleeding vs thrombotic phenotype determines therapy","safetyLevel":"critical"}'::jsonb
WHERE id = 'dic-start' AND tree_id = 'dic';

-- Node: dic-etiology-jump (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Etiology Quick-Jump","body":"[DIC Etiology Quick-Jump](#/info/dic-etiology-jump)\n\nUse the toolbar overlay to jump directly to the etiology-specific pathway:\n• **Sepsis-induced DIC** → most common; SIC scoring useful\n• **Malignancy-associated DIC** → includes APL and solid tumor (Trousseau)\n• **Obstetric DIC** → placental abruption, Amniotic Fluid Embolism, retained products, severe preeclampsia/HELLP\n• **Trauma-induced coagulopathy (TIC)** → overlaps with but distinct from classic DIC\n\nAll four pathways converge on the same hemostatic resuscitation principles in Module 4.","citation":[1,2],"next":"dic-overt-vs-non-overt","summary":"Use toolbar Etiology Quick-Jump to navigate directly to sepsis, malignancy, obstetric, or trauma pathways","skippable":true}'::jsonb
WHERE id = 'dic-etiology-jump' AND tree_id = 'dic';

-- Node: dic-obstetric (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Obstetric DIC","body":"**Obstetric DIC is rapid-onset, bleeding-dominant, and reverses with definitive obstetric management.** [12]\n\n**Triggers:** [12]\n• **Placental abruption** (most common)\n• **Amniotic Fluid Embolism** — sudden cardiopulmonary collapse + DIC\n• **Retained products of conception / fetal demise**\n• **Severe preeclampsia / HELLP**\n• **Placenta accreta spectrum / postpartum hemorrhage**\n• **Sepsis (chorioamnionitis, septic abortion)**\n\n**Key obstetric thresholds:** [12]\n• Pregnant baseline fibrinogen is 4-6 g/L\n• **Transfuse cryo if fibrinogen <2 g/L** (not <1 as in non-pregnant)\n• Falling fibrinogen <2 g/L is a strong predictor of severe PPH\n\n**Management priorities:** [12]\n1. **Definitive source control** — deliver, evacuate uterus, repair lacerations\n2. **Massive transfusion protocol** with 1:1:1 ratio if active hemorrhage\n3. **Cryoprecipitate** early to maintain fibrinogen ≥2 g/L (10 units or 0.06 units/kg)\n4. **Tranexamic acid 1 g IV** within 3 hours (WOMAN trial — reduces death from PPH)\n5. **Avoid heparin** — bleeding-dominant phenotype\n6. **Notify blood bank early** — anticipate massive transfusion\n\n**Amniotic Fluid Embolism-specific:** Rare but catastrophic; bedside echo (RV strain), ECMO consideration, multidisciplinary team. Mortality 20-60%. [12]","citation":[12],"next":"dic-trauma","summary":"OB DIC = deliver/evacuate, MTP 1:1:1, cryo to keep fibrinogen ≥2 g/L (not <1), TXA 1g IV within 3h, no heparin"}'::jsonb
WHERE id = 'dic-obstetric' AND tree_id = 'dic';

-- Node: dic-disposition (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":6,"title":"Disposition & Consults","body":"**Most DIC patients require ICU admission.** [2][3]\n\n**ICU criteria — virtually all DIC:** [2]\n• Active bleeding\n• Hemodynamic instability\n• Need for blood product resuscitation\n• Multi-organ dysfunction\n• Need for invasive monitoring or vasopressor support\n• Severe trigger (sepsis, trauma, Amniotic Fluid Embolism, APL)\n\n**Floor / step-down considerations:** [2]\n• Mild non-overt DIC with controlled trigger\n• Stable platelets and coagulation\n• No active bleeding\n• Close monitoring available\n\n**Emergent consults:** [2][11][12]\n• **Hematology** — for all DIC; co-manage product strategy and anticoagulation\n• **Critical care / ICU** — for admission and ongoing resuscitation\n• **Source-specific:**\n  - **Surgery** — for source control (abscess, perforation, trauma)\n  - **OB** — for obstetric DIC\n  - **Oncology** — for APL (heme/onc), Trousseau\n  - **Interventional radiology** — for embolization (PPH, GI bleed)\n  - **Blood bank** — for massive transfusion protocol activation\n\n**Transfer considerations:** [11]\n• APL → tertiary heme/onc center after ATRA started and stabilized\n• Severe trauma → Level 1 trauma center if not already\n• Amniotic Fluid Embolism → tertiary OB / ECMO-capable center\n\n**Communication checklist:**\n• Trigger and treatment status\n• Phenotype (bleeding vs thrombotic)\n• Latest labs and scores\n• Products given and response\n• Active interventions and pending consults","citation":[2,3,11,12],"recommendation":"ICU admission for nearly all DIC patients. Emergent hematology + source-specific consults (OB, oncology, surgery, IR). Transfer to tertiary care if APL, severe trauma, or Amniotic Fluid Embolism.","confidence":"definitive"}'::jsonb
WHERE id = 'dic-disposition' AND tree_id = 'dic';

-- Node: pph-four-ts (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"The 4 T''s of PPH","body":"[4 T''s Differential Reference](#/info/pph-four-ts-info) — full differential with clinical clues.\n\n**The 4 T''s** is the universal PPH differential. Commit it to memory — you will use it in every hemorrhage. [1][5][8]\n\n| **T** | **Cause** | **Frequency** | **Clinical clue** |\n|---|---|---|---|\n| **Tone** | Uterine atony | ~70-80% | Boggy, soft uterus; fundus above umbilicus |\n| **Trauma** | Lacerations, hematoma, inversion, uterine rupture | ~20% | Firm uterus but active bleeding |\n| **Tissue** | Retained placenta/products, accreta | ~10% | Incomplete placenta on exam; persistent bleeding |\n| **Thrombin** | Coagulopathy (DIC, Amniotic Fluid Embolism, HELLP, dilutional) | <1% | Oozing from IV sites, hematuria, petechiae |\n\n**Always check Tone first.** If the uterus is firm and well-contracted but bleeding continues — think **Trauma** or **Tissue**.\n\n**Physical exam BEFORE diving deeper:**\n• Fundus position and tone\n• Speculum exam of cervix and vagina for lacerations\n• Inspect placenta for completeness (every cotyledon, intact membranes)\n• IV site oozing, gingival bleeding, petechiae (Thrombin)","citation":[1,5,8],"next":"pph-four-ts-q","summary":"Tone (70%) → Trauma (20%) → Tissue (10%) → Thrombin (<1%). Check tone first."}'::jsonb
WHERE id = 'pph-four-ts' AND tree_id = 'pph';

-- Node: pph-four-ts-q (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Primary Cause?","body":"Based on the exam, what is the most likely primary cause of bleeding?\n\n**Tone = boggy/soft uterus**\n**Trauma = firm uterus, active bleeding from canal, or signs of inversion/rupture**\n**Tissue = incomplete placenta or persistent bleeding despite firm uterus and no lacerations**\n**Thrombin = generalized oozing (IV sites, mucosa) or known coagulopathy/Amniotic Fluid Embolism**\n\nIf unclear, default to **Tone** — it is the most common and uterotonics buy time.","options":[{"label":"Tone — Boggy uterus","description":"Uterine atony (most common)","next":"pph-atony-intro"},{"label":"Trauma — Laceration, inversion, or rupture","description":"Genital tract injury","next":"pph-trauma-assess"},{"label":"Tissue — Retained placenta/products","description":"Manual exploration needed","next":"pph-tissue"},{"label":"Thrombin — Coagulopathy","description":"DIC, Amniotic Fluid Embolism, dilutional","next":"pph-thrombin"}],"summary":"4-way branch: Tone (boggy) / Trauma (firm + bleeding) / Tissue (retained) / Thrombin (oozing)."}'::jsonb
WHERE id = 'pph-four-ts-q' AND tree_id = 'pph';

-- Node: pph-thrombin (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Thrombin — Coagulopathy","body":"**COAGULOPATHY IN PPH**\n\nLess than 1% of PPH as primary cause, but **common as a secondary complication** after massive transfusion or prolonged severe hemorrhage. Early recognition changes management.\n\n**CAUSES**\n• **Dilutional coagulopathy** — after large crystalloid or unbalanced blood product resuscitation\n• **DIC (disseminated intravascular coagulation)** — severe PPH, sepsis, abruption, intrauterine fetal demise\n• **Amniotic Fluid Embolism** — cardiogenic collapse + DIC + respiratory failure, often within minutes of delivery\n• **HELLP / severe preeclampsia** — low platelets + hepatic coagulopathy\n• **Pre-existing** — vWD, hemophilia carrier, therapeutic anticoagulation\n\n**CLINICAL CLUES**\n• Oozing from IV sites, incisions, mucosal surfaces\n• Petechiae, ecchymoses\n• Hematuria\n• Non-clotting blood in the specimen tube or on drapes\n\n**LABS** — CBC, fibrinogen, PT/PTT, INR, D-dimer, thromboelastography/ROTEM if available\n\n**MANAGEMENT**\n• **Balanced transfusion — 1:1:1 pRBC:FFP:platelets** via [Massive Transfusion Protocol](#/tree/massive-transfusion)\n• **Cryoprecipitate 10 units** if fibrinogen <200 mg/dL — maintain fibrinogen >200\n• [Platelets](#/drug/platelets/massive transfusion) to maintain >50,000 (>100,000 if ongoing bleeding)\n• **Calcium gluconate 1-2 g IV** per every 4 units blood (citrate chelation)\n• **Keep warm** — hypothermia triples coagulopathy severity\n• **Correct acidosis** — pH <7.2 impairs clotting\n• **TXA** — already given if within 3h of delivery onset\n• **Amniotic Fluid Embolism** — supportive, consider ECMO, hysterectomy; mortality ~40% [1][14]\n\n**The lethal triad: hypothermia + acidosis + coagulopathy** — treat all three. [6]","citation":[1,6,14],"next":"pph-bleeding-check","summary":"Oozing + labs (fibrinogen <200) → 1:1:1 MTP + cryo + Ca + keep warm. Treat lethal triad.","safetyLevel":"warning"}'::jsonb
WHERE id = 'pph-thrombin' AND tree_id = 'pph';

-- Node: pph-controlled (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":6,"title":"PPH Controlled — Disposition","body":"**Postpartum hemorrhage controlled with appropriate measures.**\n\n[PPH Discharge Instructions](#/info/pph-discharge) — shareable return precautions for once the patient is ready for discharge or transfer to the postpartum unit.\n\n**DISPOSITION**\n• **ICU admission** if: ≥4 units transfused, hysterectomy, hemodynamic instability, coagulopathy, Amniotic Fluid Embolism, or requiring vasopressors\n• **Step-down / OB unit** if: controlled bleeding, stable vitals, <4 units transfused, no ongoing organ dysfunction\n\n**24-HOUR MANAGEMENT GOALS**\n• Hemodynamic stability off vasopressors\n• Uterus firm and not re-bleeding\n• Hemoglobin stable (trend)\n• Fibrinogen >200 mg/dL\n• Urine output >30 mL/hr\n• VTE prophylaxis started once hemostatic\n\n**DOCUMENT**\n• Estimated blood loss (cumulative)\n• Interventions performed and their timing\n• Products transfused (pRBC, FFP, platelets, cryo, factors)\n• Primary cause (Tone / Trauma / Tissue / Thrombin)\n• Consultants involved (OB, anesthesia, IR, blood bank)\n• Debrief team after stabilization — quality improvement, emotional processing\n\n**FOLLOW-UP**\n• OB follow-up in 1-2 weeks\n• Lactation support\n• Postpartum depression screening\n• Iron supplementation as needed","citation":[1,5,8],"recommendation":"PPH controlled. Admit to ICU if ≥4 units transfused, hysterectomy, or instability; otherwise step-down / L&D. Continue oxytocin infusion 4-24h. Repeat labs at 2-4h. VTE prophylaxis (mechanical immediate, pharmacologic once hemostasis confirmed). Document cause, interventions, timing, team. OB follow-up 1-2 weeks.","confidence":"recommended"}'::jsonb
WHERE id = 'pph-controlled' AND tree_id = 'pph';

-- Node: rh-beauchops (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"BEAU-CHOPS — Reversible Causes in Pregnant Arrest","body":"**Pregnancy-specific reversible causes of cardiac arrest.** [See full BEAU-CHOPS](#/info/rh-beauchops-details)\n\n**B — Bleeding / DIC**\nHemorrhage (placenta, uterine rupture, abruption, Amniotic Fluid Embolism-DIC) — activate MTP. [Massive Transfusion](#/tree/massive-transfusion).\n\n**E — Embolism**\nPE, amniotic fluid embolism, air, fat. Amniotic Fluid Embolism is uniquely pregnancy-related and often fatal.\n\n**A — Anesthetic complications**\nHigh spinal, local anesthetic systemic toxicity (LAST) — give [Intralipid](#/drug/lipid-emulsion/last) 1.5 mL/kg bolus.\n\n**U — Uterine atony**\nMassive hemorrhage from atony after delivery — [Oxytocin](#/drug/oxytocin/postpartum hemorrhage), TXA, massage.\n\n**C — Cardiac disease**\nMI, [Peripartum Cardiomyopathy](#/tree/peripartum-cardiomyopathy), aortic dissection, congenital disease.\n\n**H — Hypertension**\n[Eclampsia](#/tree/eclampsia), preeclampsia with stroke/ICH, HELLP.\n\n**O — Other (standard ACLS H''s/T''s + magnesium toxicity)**\nHypoxia, hypovolemia, hypokalemia, hypothermia, tension PTX, tamponade, toxins, thrombosis. **Magnesium toxicity** is a pregnancy-specific cause — if patient was on MgSO4 for eclampsia/preterm labor, give [Calcium Gluconate](#/drug/calcium-gluconate/hypermagnesemia) 1 g IV or [Calcium Chloride](#/drug/calcium-chloride/hypermagnesemia) 1 g IV.\n\n**P — Placenta previa / abruption**\nMassive antepartum hemorrhage — prepare for RH + transfusion.\n\n**S — Sepsis**\nChorioamnionitis, pyelonephritis (common in pregnancy), pneumonia. [Sepsis](#/tree/sepsis).\n\n**TREAT THE CAUSE WHILE YOU CLOCK-WATCH.** Finding a reversible cause in the first 4 minutes may obviate the need for RH. [1][4][14]","citation":[1,4,14],"next":"rh-decision-point","summary":"BEAU-CHOPS: Bleeding, Embolism, Anesthetic, Uterine atony, Cardiac, HTN, Other, Placenta, Sepsis.","skippable":true}'::jsonb
WHERE id = 'rh-beauchops' AND tree_id = 'resuscitative-hysterotomy';

-- Node: rh-placenta (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Step 5 — Deliver the Placenta","body":"**DELIVER THE PLACENTA:**\n\n• **Gentle cord traction** — one hand on the cord, steady pull\n• **Other hand on the fundus** — apply counter-pressure to guard against uterine inversion\n• Placenta should separate and deliver within 30-60 seconds\n\n**IF PLACENTA DOES NOT DELIVER WITHIN 1-2 MINUTES:**\n• **Manual extraction** — reach into the uterus, sweep the placental edge off the uterine wall with the side of your hand, deliver manually\n• **Do not force** — if adherent, may be [placenta accreta](#/tree/pregnancy-trauma) — continue resuscitation and get to OR\n\n**AFTER PLACENTAL DELIVERY:**\n• **Aortocaval compression is now fully relieved**\n• Chest compressions become dramatically more effective\n• **Watch for ROSC** — this is the moment it often happens [2][3]\n\n**SAVE THE PLACENTA** for pathology if possible (bag or basin). Useful for identifying cause of arrest (Amniotic Fluid Embolism, abruption, infection).","citation":[1,2,3],"next":"rh-continue-cpr","summary":"Gentle cord traction + fundal counter-pressure. Manual extraction if stuck. ROSC often happens here."}'::jsonb
WHERE id = 'rh-placenta' AND tree_id = 'resuscitative-hysterotomy';

-- Node: rh-rosc-postop (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Maternal ROSC — Post-Arrest Care","body":"**ROSC ACHIEVED AFTER RESUSCITATIVE HYSTEROTOMY.**\n\n**IMMEDIATE PRIORITIES (the next 15 minutes):**\n\n1. **Hemostasis** — uterine atony is near-universal after RH. Proceed to [Uterine Atony Management](#/node/rh-uterine-atony).\n2. **Massive transfusion** — activate MTP if not already. Expected blood loss 1-2+ L. [Massive Transfusion](#/tree/massive-transfusion).\n3. **Airway secured** — intubate if not already\n4. **Hemodynamic support** — [Norepinephrine](#/drug/norepinephrine/post-cardiac arrest) infusion, arterial line, central line\n5. **Identify and treat cause** — what put her in arrest? (PE? Amniotic Fluid Embolism? hemorrhage? MI? eclampsia?)\n6. **Prophylactic antibiotics** — [Cefazolin](#/drug/cefazolin/surgical prophylaxis) 2 g IV (the field was non-sterile)\n7. **Definitive surgical closure** — transfer to OR\n\n**POST-ARREST CARE BUNDLE (standard + pregnancy-specific):**\n• Targeted temperature management — 32-36°C for 24 hours (safe in postpartum)\n• Maintain SBP ≥90, MAP ≥65\n• Glucose control 140-180\n• Lung-protective ventilation\n• Continuous EEG if altered\n• Serial exams for neuro recovery\n\n**TRANSFER TO OR** for formal closure, continued hemostasis, and definitive management.\n\n**ICU admission** with OB/MFM, ICU, anesthesia co-management. [1][2][4]","citation":[1,2,4],"next":"rh-uterine-atony","summary":"ROSC post-RH: hemostasis, MTP, airway, pressors, find cause, OR for closure, ICU with MFM/ICU.","safetyLevel":"critical"}'::jsonb
WHERE id = 'rh-rosc-postop' AND tree_id = 'resuscitative-hysterotomy';

-- Node: rh-continued-arrest (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":6,"title":"Continued Arrest After Hysterotomy","body":"**NO ROSC AFTER RESUSCITATIVE HYSTEROTOMY.**\n\nThe aortocaval decompression maneuver did not achieve ROSC. Continue aggressive resuscitation.\n\n**CONTINUE FOR AT LEAST 10 MORE MINUTES (post-delivery):**\n• Standard ACLS — epinephrine q3-5 min, rhythm-appropriate shocks\n• Reassess and treat reversible causes\n• Consider [Intralipid](#/drug/intralipid-20/last) if LAST possible\n• Ultrasound — rule out tamponade, tension PTX, massive hemorrhage, Amniotic Fluid Embolism\n• Massive transfusion if hemorrhage suspected\n\n**CONSIDER:**\n• **ECMO** — [ECMO](#/tree/ecmo) — if available and arrest is clearly reversible (PE, drug OD)\n• **Open chest cardiac massage** — if penetrating trauma, hemorrhage, tamponade\n• **Continued CPR for much longer than usual** — pregnant patients have tolerated prolonged arrest with good outcomes; maternal survival reported after >30 min of CPR\n\n**IF REFRACTORY — TERMINATION OF RESUSCITATION:**\nPer standard criteria when all reversible causes excluded:\n• No ROSC after exhaustive resuscitation\n• No shockable rhythm for extended period\n• ETCO2 <10 mmHg after adequate CPR\n• Team consensus\n\nThis is an ethically complex decision. Involve senior personnel, document thoroughly, support the family and team.","citation":[1,2,9],"recommendation":"Continue full resuscitation for at least 10 more min post-delivery. Consider ECMO, open chest if indicated. Pregnant patients tolerate prolonged arrest — err toward longer resuscitation.","confidence":"recommended"}'::jsonb
WHERE id = 'rh-continued-arrest' AND tree_id = 'resuscitative-hysterotomy';

-- Node: rh-disposition (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":6,"title":"Disposition & Transfer","body":"**FINAL DISPOSITION AFTER MATERNAL ROSC + RESUSCITATIVE HYSTEROTOMY:**\n\n**IMMEDIATE (next 30 minutes):**\n• **Transfer to OR** — formal surgical closure, uterine repair, hemostasis verification\n• **Blood products continuing** — MTP until hemostasis, goal fibrinogen >200, platelets >50\n• **Arterial line, central line** placed\n• **OB + trauma surgery + anesthesia** at bedside in OR\n\n**NEONATE:**\n• **Level III NICU** for post-arrest neonatal care\n• Therapeutic hypothermia per NICU protocol if HIE criteria met\n• Head imaging, EEG monitoring, metabolic panel\n\n**MATERNAL ICU:**\n• Post-cardiac-arrest care bundle\n• Targeted temperature management 32-36°C for 24 hours (safe in postpartum — no increased bleeding risk demonstrated)\n• MFM + ICU + anesthesia co-management\n• Continuous EEG if altered\n• Serial neuro exams\n\n**CAUSE WORKUP:**\n• Complete metabolic, toxicology, coagulation panels\n• CT chest/abdomen/pelvis\n• Echo\n• Autopsy of placenta (Amniotic Fluid Embolism, abruption, infection)\n• Cardiology, MFM, hematology, ID consults as indicated\n\n**FAMILY, TEAM, LEGAL:**\n• Family: compassionate, clear communication throughout\n• Debrief the team — this is emotionally demanding for all involved\n• Chaplain / social work for family support\n• Document thoroughly — times, interventions, decisions, personnel\n• Risk management notification per institutional policy\n\n**LONG-TERM:**\n• Maternal outcome depends on cause of arrest\n• Neonatal outcome depends on arrest-to-delivery time and post-delivery care\n• Both patients need long-term follow-up","citation":[1,2,4],"recommendation":"OR for formal closure. ICU with MFM/ICU co-management, post-arrest care bundle, TTM. Level III NICU for neonate. Cause workup. Team debrief and family support.","confidence":"recommended"}'::jsonb
WHERE id = 'rh-disposition' AND tree_id = 'resuscitative-hysterotomy';

COMMIT;